import{t as e}from"./jsx-runtime-lw2jiZar.js";import{t}from"./activity-BFe0pMCz.js";import{C as n,E as r,M as i,N as a,O as o,P as s,_ as c,b as l,j as u,k as d,l as f,n as p,o as m,t as h,w as g,x as _}from"./shared-DhavWP79.js";import{t as v}from"./database-LLH4Psoh.js";import{D as y}from"./index-CPmvoNjB.js";import{t as b}from"./CodeEditor-BZlrvoTL.js";var x=e();function S({module:e}){return(0,x.jsxs)(a,{children:[(0,x.jsx)(i,{variant:`project`,chip:e??`Месяц 2 · Блок 8`,title:`Регрессия команд, сохранений и безопасной сборки`,intro:`Отдельная команда уже отделена от цикла CLI. Теперь проверим, что её сообщение, состояние Planner и сохранение сходятся в один предсказуемый результат.`,tags:[{icon:(0,x.jsx)(t,{size:14}),label:`регрессия CLI`},{icon:(0,x.jsx)(v,{size:14}),label:`состояние и storage`},{icon:(0,x.jsx)(y,{size:14}),label:`безопасная сборка`}]}),(0,x.jsxs)(s,{number:`00`,title:`От отдельной команды к доказанному поведению`,children:[(0,x.jsx)(o,{children:`До этого мы проверяли модель, сервис, хранилище и границу одной команды. Осталось убедиться, что эти части правильно сотрудничают в коротком пользовательском действии.`}),(0,x.jsx)(d,{variant:`connected`,items:[{title:`Точка старта`,description:`Мы вызываем execute_command отдельно от цикла run и можем передать ему функции чтения и вывода.`},{title:`Новый вопрос`,description:`Мы хотим знать не только текст ответа, но и какие данные изменились, было ли сохранение и кто его вызвал.`},{title:`Результат`,description:`Мы добавим регрессионные тесты команды, наблюдения storage и безопасной сборки готового сервиса.`}]}),(0,x.jsx)(`p`,{children:`Такая проверка связывает уже знакомые части через их настоящие договоры. Мы не переписываем CLI, сервис или хранилище ради теста. Вместо этого подаём команде управляемый ввод и наблюдаем ответ, состояние и сохранение.`})]}),(0,x.jsxs)(s,{number:`01`,title:`Тест одной команды проверяет путь пользователя`,children:[(0,x.jsx)(o,{children:`Регрессионный тест сохраняет ожидание о поведении, которое уже работало. Если последующая правка его сломает, тест покажет расхождение до того, как оно попадёт в обычный запуск.`}),(0,x.jsx)(`p`,{children:`Для CLI важно вызвать execute_command, а не проверять только метод PlannerService. Одна команда проходит разбор входа, действие сервиса и подготовку сообщения. Тест наблюдает эту границу, но не запускает бесконечный цикл run и не подменяет прикладную операцию ручным вызовом.`}),(0,x.jsx)(`p`,{children:`Представим контрольный пункт на маршруте посылки. Мы сверяем адрес, отметку о передаче и запись в журнале: одной квитанции недостаточно, если посылка попала не тому получателю. Так же и здесь: строка «задача добавлена» не доказывает, что у задачи верные поля и что storage получил новый набор. Эта аналогия помогает разделить наблюдения, но сама по себе не доказывает восстановление после перезапуска.`}),(0,x.jsx)(`p`,{children:`Удобно мыслить последовательностью «подготовить, вызвать, сверить». Сначала создаём свежие данные и callbacks, затем один раз вызываем команду, после этого независимо проверяем сообщения, объект Task и сохранение. Если вызвать только add_task, мы обойдём разбор команды и подготовку ответа. Если запустить весь run, к вопросу добавятся цикл и выход из сессии. Граница execute_command отвечает ровно на вопрос о поведении одной команды.`}),(0,x.jsx)(l,{question:`Что мы проверяем, когда вызываем execute_command напрямую?`,options:[`Поведение одной команды через границу CLI`,`Весь бесконечный цикл run и отдельный процесс приложения`,`Только внутреннюю реализацию метода сервиса`],correctIndex:0,explanation:`Один вызов проверяет командный путь и его наблюдаемые результаты. Полный путь приложения проверяется отдельно.`})]}),(0,x.jsxs)(s,{number:`02`,title:`Переданные read и write управляют наблюдением`,children:[(0,x.jsx)(o,{children:`Когда execute_command получает функции read и write, тест может отвечать на запросы и собирать сообщения без подмены глобальных input и print.`}),(0,x.jsx)(`p`,{children:`Функция чтения отвечает на запрос CLI, а функция вывода принимает подготовленное сообщение. Для теста достаточно небольшой очереди ответов и списка результатов. Мы заранее задаём только те ответы, которые команда действительно запросит; если неверное значение запускает повторный вопрос, очередь должна содержать и следующий ответ.`}),(0,x.jsx)(b,{caption:`управляемый ввод и собранный вывод, фрагмент теста`,code:`answers = ["Разобрать отчёт", "3"]
messages = []

def read(_prompt):
    return answers.pop(0)

def write(message):
    messages.append(message)`}),(0,x.jsx)(`p`,{children:`Это похоже на репетицию сцены с заранее известными репликами и записью услышанного. Мы управляем только входом и наблюдаем вывод; обработчик и сервис остаются настоящими. Репетиция не доказывает, как текст выглядит в терминале пользователя, поэтому после автоматической проверки сохраняем короткий ручной проход CLI.`}),(0,x.jsx)(_,{question:`Как мы отличим вывод команды от её действия в данных?`,hint:`Назовите два независимых наблюдения после одного вызова.`,answer:(0,x.jsx)(`p`,{children:`Мы отдельно проверяем собранные сообщения и состояние через сервис или хранилище. Тест проходит только когда оба результата соответствуют договору команды.`})})]}),(0,x.jsxs)(s,{number:`03`,title:`Композиционная обёртка считает обращения к storage`,children:[(0,x.jsx)(o,{children:`Текст и состояние уже можно проверить, но чтобы подтвердить отсутствие лишней записи, нужно наблюдать вызовы load и save.`}),(0,x.jsx)(`p`,{children:`Для этого тестовая обёртка содержит настоящий MemoryStorage. Она считает обращения и передаёт каждую операцию внутреннему объекту. Данные по-прежнему хранит MemoryStorage, а обёртка добавляет только наблюдение. Это композиция: один объект использует другой как свою часть, не наследует его состояние и не реализует второй CRUD.`}),(0,x.jsx)(b,{caption:`независимый пример наблюдения за списком`,code:`class AppendObserver:
    def __init__(self, values):
        self.values = values
        self.calls = 0

    def append(self, value):
        self.calls += 1
        return self.values.append(value)

values = ["черновик"]
observer = AppendObserver(values)
observer.append("проверка")`}),(0,x.jsx)(`p`,{children:`Здесь обёртка держит ссылку на список, увеличивает счётчик и делегирует append тому же списку. В тесте storage устроен аналогично: счётчик принадлежит обёртке, а список Task остаётся внутри MemoryStorage. Мы не копируем данные в наблюдателе, иначе проверяли бы уже другой путь.`}),(0,x.jsx)(`p`,{children:`События можно хранить по порядку, например в списке строк «load» и «save». Тогда тест видит не только число записей, но и путь, по которому команда дошла до них. Обычно проверяем лишь те детали, которые входят в договор: изменение должно вызвать один save, чтение не должно сохранять снимок. Не фиксируем внутреннее число чтений, если оно не обещано пользователю и может измениться при безопасном рефакторинге.`}),(0,x.jsx)(h,{caption:`Одна команда и наблюдение за её данными`,children:(0,x.jsxs)(m,{label:`Вызов команды и передача storage`,children:[(0,x.jsx)(f,{title:`Тест`,shape:`input-output`,children:(0,x.jsx)(`p`,{children:`Передаёт read, собирает write`})}),(0,x.jsx)(p,{label:`запускает`}),(0,x.jsx)(f,{title:`Одна команда`,shape:`subprocess`,children:(0,x.jsx)(`p`,{children:`CLI обрабатывает ввод`})}),(0,x.jsx)(p,{label:`вызывает`}),(0,x.jsx)(f,{title:`Сервис`,children:(0,x.jsx)(`p`,{children:`Меняет данные`})}),(0,x.jsx)(p,{label:`load / save`}),(0,x.jsx)(f,{title:`Счётчик`,children:(0,x.jsx)(`p`,{children:`Считает вызовы`})}),(0,x.jsx)(p,{label:`делегирует`}),(0,x.jsx)(f,{title:`Память`,shape:`database`,children:(0,x.jsx)(`p`,{children:`Хранит задачи`})})]})}),(0,x.jsx)(`p`,{children:`Читаем схему слева направо: тест управляет одной командой, сервис обращается к storage, а обёртка наблюдает и передаёт вызов внутренней памяти. Сообщения возвращаются через write, данные можно сверить через MemoryStorage, а число вызовов видно на обёртке. Каждый результат принадлежит своему наблюдателю.`}),(0,x.jsx)(c,{code:`values = ["черновик"]
observer = AppendObserver(values)
observer.append("проверка")
print(observer.calls, values)`,output:`1 ["черновик", "проверка"]`,hint:`Обёртка увеличивает calls один раз, затем вызывает append у исходного списка.`})]}),(0,x.jsxs)(s,{number:`04`,title:`Сохранение проверяется вместе с изменением`,children:[(0,x.jsx)(o,{children:`Проверки save описывают предметное правило: читающая команда не записывает снимок, новое изменение сохраняется один раз, а повтор уже выполненного действия не создаёт лишнюю запись.`}),(0,x.jsx)(`p`,{children:`Для add мы проверяем успешное сообщение, поля созданной Task и одно сохранение. Для list, find, search и stats проверяем нужный результат и ноль вызовов save. Успешный переход done или удаление меняют данные и сохраняют новый набор. Повтор done оставляет задачу выполненной, но повторная запись не нужна.`}),(0,x.jsx)(`p`,{children:`Ошибочное значение и неизвестный id не меняют список и не вызывают save. Сравним состояние до и после команды, а не ограничимся сообщением. Иначе обработчик может вежливо сообщить об ошибке уже после того, как повредил данные.`}),(0,x.jsx)(`p`,{children:`Запись и изменение в памяти при этом не становятся одной транзакцией. Если save завершился StorageError после изменения объекта, состояние в памяти могло измениться. Тест подтверждает, что успех не напечатан, но не должен требовать отката, которого приложение не обещает.`}),(0,x.jsx)(`p`,{children:`Параметризация полезна для похожих сценариев, у которых одинаковая подготовка и форма проверки: например, add, done и delete меняют набор, но каждое действие получает собственные ответы и ожидаемый эффект. Не объединяем в один нечитаемый тест все ветви CLI. Пользовательский отказ, ошибка хранения и выход из сессии отвечают на разные вопросы, поэтому их проще оставить отдельными случаями с ясными именами.`}),(0,x.jsx)(g,{title:`Соберём проверку одной команды`,prompt:`Выберите порядок, который связывает ответ пользователя, действие и доказательства результата.`,pieces:[{id:`fresh`,code:`создать свежие MemoryStorage и PlannerService`,note:`состояние этого теста не приходит от соседнего`},{id:`callbacks`,code:`подготовить ответы read и сборщик write`,note:`ввод и сообщения принадлежат тесту`},{id:`call`,code:`вызвать execute_command один раз`,note:`проверяется реальная граница CLI`},{id:`assert`,code:`сверить результат, состояние и число save`,note:`каждый эффект имеет отдельное ожидание`}],correctOrder:[`fresh`,`callbacks`,`call`,`assert`],explanation:`Свежая зависимость изолирует тест, callbacks задают пользовательский обмен, один вызов проходит через настоящий CLI, а проверки фиксируют результат и эффект.`,incorrectExplanation:`Сначала подготовим независимое состояние и ответы, затем вызовем одну команду и только после этого сравним сообщения, данные и save.`})]}),(0,x.jsxs)(s,{number:`05`,title:`Пользовательский отказ и StorageError имеют разные границы`,children:[(0,x.jsx)(o,{children:`Регрессия полезна, когда она не превращает любую ошибку в ожидаемый успех. Поэтому тест различает отказ данных, отказ хранения и непредвиденный дефект.`}),(0,x.jsx)(`p`,{children:`Неверный приоритет или неизвестный id относятся к понятному ответу одной команды. Неизвестная команда также не завершает сессию. StorageError сообщает, что приложение не смогло прочитать или сохранить данные, и проходит к уже существующей границе остановки. TypeError или NameError в тестируемом коде не являются ошибкой пользователя: мы оставляем их видимыми, чтобы исправить источник.`}),(0,x.jsx)(`p`,{children:`Проверяя ожидаемый отказ, называем его конкретный тип через pytest.raises или сверяем предусмотренное сообщение и неизменное состояние. Широкий except Exception делает красный сценарий зелёным независимо от причины. Так тест перестаёт защищать договор и становится занавесом перед дефектом.`}),(0,x.jsx)(n,{code:`try:
    execute_command(service, "add", read=read, write=write)
except Exception:
    messages.append("Команда выполнена")`,question:`Почему этот тест может пропустить сломанный CLI?`,options:[`Любой дефект превращается в сообщение об успехе`,`pytest запрещает проверять функции CLI`,`Список messages нельзя передавать функции`],correctIndex:0,explanation:`Общий перехват скрывает неожиданный тип ошибки и выдаёт ложный успех. Мы проверяем конкретный договор или позволяем дефекту упасть.`,fix:`with pytest.raises(StorageError):
    execute_command(service, "add", read=read, write=write)`})]}),(0,x.jsxs)(s,{number:`06`,title:`Безопасная сборка выбирает зависимость, но не запускает её`,children:[(0,x.jsx)(o,{children:`Точка сборки связывает сервис с выбранным storage. Само создание объектов не должно вызывать input, запускать CLI, читать файл или сохранять данные.`}),(0,x.jsx)(`p`,{children:"`build_service(storage=None)` различает два намерения. Если мы явно передали MemoryStorage, даже пустой экземпляр остаётся выбранной зависимостью. Если аргумент равен None, обычный запуск создаёт JsonStorage с рабочим путём. Проверка `storage is None` выражает договор точнее, чем выбор через истинность: пустое состояние не означает отсутствие объекта."}),(0,x.jsx)(`p`,{children:`Это похоже на подготовку сцены: режиссёр расставляет декорации и назначает исполнителей, но действие не начинается, пока не подан сигнал. Так и build_service соединяет готовые объекты, а main запускает сессию отдельно. Аналогия ограничена моментом сборки: после запуска storage уже выполняет настоящие операции и ошибки хранения должны сохранять свою границу.`}),(0,x.jsx)(r,{tone:`info`,children:`Проверим передачу зависимости через её наблюдаемое поведение. Сборка с тестовым storage не вызывает его load/save; последующая команда обращается к тому же объекту. Для обычной сборки убеждаемся, что выбран JsonStorage, не читая и не меняя пользовательский файл.`}),(0,x.jsx)(`p`,{children:`Проверку импорта проводим в отдельном процессе: новый интерпретатор импортирует app.main, а тест собирает код завершения и стандартный вывод. Это помогает обнаружить меню или ввод, случайно запущенные на уровне модуля. Сам тест не вызывает main и не открывает рабочее хранилище. Если когда-нибудь понадобится проверить реальную запись, для неё готовят временный путь, а не используют данные разработчика.`}),(0,x.jsx)(`p`,{children:`Безопасный импорт тоже часть договора: объявление функций и классов не показывает меню и не требует ввода. В этом шаге проверяем import и сборку; отдельный запуск проекта из чистой копии и новый процесс с данными остаются подтверждением занятия 44.`}),(0,x.jsx)(_,{question:`Почему мы проверяем storage is None, а не просто выбираем storage через or?`,hint:`Отделите переданный пустой объект от отсутствующей зависимости.`,answer:(0,x.jsx)(`p`,{children:`None означает, что зависимость не передали. Пустой MemoryStorage всё равно является выбранным объектом и должен сохраниться в сборке.`})})]}),(0,x.jsxs)(s,{number:`07`,title:`Отдельные регрессии готовят сквозную приёмку`,children:[(0,x.jsx)(o,{children:`Командные тесты связывают callback, сервис, storage и данные, но каждый сценарий сохраняет одну ясную причину возможного падения.`}),(0,x.jsx)(`p`,{children:`Мы покрываем add, list, find, search, done, delete, stats и exit: проверяем предусмотренный вывод, результат команды, нужные поля и количество записей. Отдельные случаи подтверждают неизвестную команду и id, неверный ввод, повторный done, отказ load/save и безопасный build_service. Так при ошибке видно, нарушен ли пользовательский ответ, состояние или граница сохранения.`}),(0,x.jsx)(`p`,{children:`Свежая MemoryStorage нужна каждому сценарию, иначе один тест может унаследовать задачу от другого. Наблюдательная обёртка также создаётся заново и содержит только состояние счётчиков. Мы не чистим рабочий JSON и не используем его как фикстуру. Для этой цели файловые проверки предыдущего шага уже используют отдельный tmp_path.`}),(0,x.jsx)(`p`,{children:`Раздельные ожидания помогают быстро найти слой сбоя. Верное сообщение при неверных полях Task указывает на действие или подготовку данных. Верное состояние при лишнем save показывает ошибку на границе хранения. Побочный вывод только при импорте указывает на запуск кода уровня модуля. Поэтому не объединяем все доказательства в один общий assert: каждый из них отвечает на свой вопрос и сохраняет полезную подсказку при падении.`}),(0,x.jsx)(`p`,{children:`Набор командных тестов дополняет, а не заменяет сквозное прохождение. В следующем занятии мы соединим операции и восстановление на изолированном JSON, после чего повторим пользовательский маршрут. Если здесь зелёные тесты, это подтверждает границу одной команды и сборки, но не доказывает весь путь нового процесса.`})]}),(0,x.jsxs)(s,{number:`08`,title:`Что мы будем делать в практике`,children:[(0,x.jsx)(o,{children:`Практика продолжает результат прошлого шага: один PlannerService, выбранный storage, готовая команда и рабочие пользовательские договоры. Мы добавим регрессионное доказательство их сотрудничества.`}),(0,x.jsx)(d,{variant:`connected`,items:[{title:`Подготовим наблюдение`,description:`Создадим свежие read/write callbacks и композиционную обёртку вокруг MemoryStorage; получим управляемый ввод и счётчики load/save.`},{title:`Проверим команды`,description:`Вызовем существующие команды через execute_command и сверим сообщения, результат, поля Task и продолжение сессии.`},{title:`Проверим побочные эффекты`,description:`Подтвердим один save после нового изменения и отсутствие save при чтении, неверных данных и повторном done.`},{title:`Проверим границы отказа`,description:`Различим ожидаемый отказ команды, StorageError и дефект программы; убедимся, что ошибка сохранения не выдаётся за успех.`},{title:`Проверим сборку`,description:`Передадим пустой MemoryStorage, проверим выбор JsonStorage по умолчанию и импорт без запуска меню или записи.`},{title:`Повторим регрессию`,description:`Запустим тесты отдельно и вместе, затем вручную пройдём штатный CLI без изменения набора команд.`}]}),(0,x.jsx)(`p`,{children:`Сначала проверим фактический вход проекта: эти тесты применимы после того, как результат занятия 42 действительно содержит execute_command, read/write и безопасный build_service. Если текущий checkout ещё на более раннем этапе, сначала восстановим предусмотренную последовательность, а не создадим пустые тесты вокруг отсутствующих модулей.`}),(0,x.jsx)(`p`,{children:`В итоге останется набор регрессий реальной командной границы, зависимостей и сохранения. Он подготавливает сквозное испытание следующего занятия, не добавляя новую продуктовую функцию и не обещая транзакционный откат после ошибки записи.`}),(0,x.jsx)(u,{text:`Добавьте регрессионные тесты существующего CLI-пути и безопасной сборки, проверяя вывод, состояние и сохранения отдельно.`})]})]})}export{S as Lesson42_1};